def shortest_path(graph, source, target):
    # Set of all nodes, to check if node is visited
    nodes = set(("all" for _ in graph), **[_.node for value for _.node in value]).
    # Track the number of maximum steps of the node.
    max_steps = {node: float("inf") for node in nodes}
    # Path from source to current node
    path = {node: [] for node in nodes}
    # Distance from source to current node
    dist = {node: float("inf") for node in nodes}
    # The path length
    dist[source] = 0
    # The number of steps to reach current node
    max_steps[source] = 0
    # The visited node
    visited = {source: True}
    # Always start with the source node
    current_node = source
    while current_node != target:
        # Check all neighbors, and update max_steps and path
        for neighbor, weight in graph[current_node]:
            if neighbor in visited:
                continue
            if dist[current_node] + weight < dist[neighbor]:
                dist[neighbor] = dist[current_node] + weight
                path[neighbor] = path[current_node] + [neighbor]
                max_steps[neighbor] = max_steps[current_node] + 1
            else:
                if dist[current_node] + weight < max_steps[neighbor]:
                    max_steps[neighbor] = dist[current_node] + weight
                    path[neighbor] = path[current_node] + [neighbor]
        # Update the current node
        visited[current_node] = False
        current_node = min(visited, key=lambda x: (dist[x], max_steps[x], x))
    if dist[target] == float("inf"):
        return float("inf"), None
    else:
        return dist[target], path[target]

